sys_variable_value.value:
(function execute(inputs, outputs) {
    try {
        var r = new sn_ws.RESTMessageV2();
        r.setHttpMethod("POST");
        r.setEndpoint(gs.getProperty('glide.servlet.uri') + '/api/x_vuram_abnormal_0/transaction_api');

        // Prepare JSON body
        var requestBody = {
            accountNumber: inputs.accountNumber
        };
        r.setRequestBody(JSON.stringify(requestBody));
        r.setRequestHeader("Content-Type", "application/json");

        var response = r.execute();
        var httpStatus = response.getStatusCode();
        var responseBody = response.getBody();

        // Assign outputs (must match Action’s defined outputs)
        outputs.httpstatus = httpStatus;
        outputs.responsebody = responseBody;

        // Parse JSON and extract values
        try {
            var parsed = JSON.parse(responseBody);
            outputs.parsedresponse = parsed;

            // Pull values from parsed object
            if (parsed.totalCredit !== undefined && parsed.totalDebit !== undefined) {
                outputs.totalcredit = parsed.totalCredit;
                outputs.totaldebit = parsed.totalDebit;
            }
        } catch (e) {
            outputs.parsedresponse = { error: "Invalid JSON", raw: responseBody };
        }

    } catch (ex) {
        outputs.httpstatus = -1;
        outputs.responsebody = ex.message;
        outputs.parsedresponse = { error: ex.message };
    }
})(inputs, outputs);

